import{_ as e,o as d,c as o,ao as i}from"./chunks/framework.DAbzcW3k.js";const y=JSON.parse('{"title":"Inputs","description":"","frontmatter":{},"headers":[],"relativePath":"inputs.md","filePath":"inputs.md","lastUpdated":null}'),a={name:"inputs.md"};function r(l,t,n,s,c,h){return d(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="Inputs" tabindex="-1">Inputs <a class="header-anchor" href="#Inputs" aria-label="Permalink to &quot;Inputs {#Inputs}&quot;">​</a></h1><p>Every input is optional. A method&#39;s <code>_model</code> is the 3D volume and its <code>_data</code> is the measured dataset for the same method.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Input</th><th style="text-align:right;">Formats</th><th style="text-align:right;">Loaded as</th></tr></thead><tbody><tr><td style="text-align:right;"><code>MT_model</code></td><td style="text-align:right;">ModEM/WS <code>.rho</code></td><td style="text-align:right;">Resistivity volume</td></tr><tr><td style="text-align:right;"><code>MT_data</code></td><td style="text-align:right;">ModEM <code>.dat</code></td><td style="text-align:right;">Georeferences the mesh; <strong>Show Data</strong> draws the site locations</td></tr><tr><td style="text-align:right;"><code>gravity_model</code></td><td style="text-align:right;"><code>.xyz</code>, <code>.vox</code></td><td style="text-align:right;">Density volume, displayed in g/cc</td></tr><tr><td style="text-align:right;"><code>gravity_data</code></td><td style="text-align:right;"><code>.xyz</code></td><td style="text-align:right;"><strong>Show Data</strong> draws the survey points at their own elevation</td></tr><tr><td style="text-align:right;"><code>magnetic_model</code></td><td style="text-align:right;"><code>.xyz</code>, <code>.vox</code></td><td style="text-align:right;">Susceptibility volume</td></tr><tr><td style="text-align:right;"><code>magnetic_data</code></td><td style="text-align:right;"><code>.xyz</code></td><td style="text-align:right;"><strong>Show Data</strong> draws the survey points</td></tr><tr><td style="text-align:right;"><code>seismic_data</code></td><td style="text-align:right;">SEG-Y</td><td style="text-align:right;">Seismic curtain and model drape</td></tr><tr><td style="text-align:right;"><code>shapefiles</code></td><td style="text-align:right;"><code>.shp</code></td><td style="text-align:right;">Linework, each entry with its own <code>color</code>, <code>width</code> and <code>alpha</code></td></tr></tbody></table><h2 id="What-you-get" tabindex="-1">What you get <a class="header-anchor" href="#What-you-get" aria-label="Permalink to &quot;What you get {#What-you-get}&quot;">​</a></h2><p>What you get depends on what you configure:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Configured</th><th style="text-align:right;">Result</th></tr></thead><tbody><tr><td style="text-align:right;">Nothing</td><td style="text-align:right;">An empty 3D scene, sized to the shapefiles or seismic line if there are any</td></tr><tr><td style="text-align:right;"><code>MT_model</code> only</td><td style="text-align:right;">The model in its own local coordinates; georeferenced overlays are left out</td></tr><tr><td style="text-align:right;"><code>MT_model</code> + <code>MT_data</code></td><td style="text-align:right;">Georeferenced into <code>coordinate.target_crs</code></td></tr><tr><td style="text-align:right;">A gravity/magnetic model with an MT model</td><td style="text-align:right;">Resampled onto the MT cells, so the properties compare cell for cell</td></tr><tr><td style="text-align:right;">A gravity/magnetic model without one</td><td style="text-align:right;">Gridded on axes taken from its own coordinates</td></tr></tbody></table><h2 id="Reading-point-files" tabindex="-1">Reading point files <a class="header-anchor" href="#Reading-point-files" aria-label="Permalink to &quot;Reading point files {#Reading-point-files}&quot;">​</a></h2><p><code>.xyz</code> models and surveys are <code>longitude latitude elevation value</code> records, or easting/northing in any projected CRS. They are reprojected into the project CRS and, for models, resampled onto the scene&#39;s cells.</p><h3 id="Source-CRS-detection" tabindex="-1">Source CRS detection <a class="header-anchor" href="#Source-CRS-detection" aria-label="Permalink to &quot;Source CRS detection {#Source-CRS-detection}&quot;">​</a></h3><p>A file that states no CRS has one worked out for it. Degrees and projected metres never overlap in practice: longitude/latitude is bounded by ±180/±90, while a metric CRS puts survey data tens to hundreds of kilometres from its false origin. A file is therefore read as WGS84 lon/lat or as already being in the project CRS accordingly. When both columns fall inside ±90 and the lon/lat order is ambiguous, the project CRS&#39;s declared area of use decides which column is longitude, so latitude-first files land in the right place too. <code>.prj</code> files and ModEM origins are still read from the file itself.</p>',10)])])}const u=e(a,[["render",r]]);export{y as __pageData,u as default};
